/* Intermediate4 · Preserve invoices, price object granularity and verify archive access. */
(function(){
  const N=AG.aws.n,NOW='2026-10-26T00:00:00Z',UNTIL='2033-10-26T00:00:00Z',ROLE='arn:aws:iam::123456789012:role/shop-replication';
  const LC=()=>({Rules:[{ID:'archive-large-logs',Status:'Enabled',Filter:{And:{Prefix:'logs/aggregated/',ObjectSizeGreaterThan:131071}},Transitions:[{Days:30,StorageClass:'STANDARD_IA'},{Days:180,StorageClass:'GLACIER'}]},{ID:'noncurrent-cleanup',Status:'Enabled',Filter:{Prefix:'logs/'},NoncurrentVersionTransitions:[{NoncurrentDays:30,StorageClass:'STANDARD_IA'}],NoncurrentVersionExpiration:{NoncurrentDays:365}},{ID:'abort-incomplete',Status:'Enabled',Filter:{Prefix:'logs/'},AbortIncompleteMultipartUpload:{DaysAfterInitiation:7}}]});
  const LOCK=()=>({ObjectLockEnabled:'Enabled',Rule:{DefaultRetention:{Mode:'COMPLIANCE',Years:7}}}),RETENTION=()=>({Mode:'COMPLIANCE',RetainUntilDate:UNTIL});
  const REPL=()=>({Role:ROLE,Rules:[{ID:'invoices-crr',Priority:1,Status:'Enabled',Filter:{Prefix:'invoices/'},DeleteMarkerReplication:{Status:'Disabled'},Destination:{Bucket:'arn:aws:s3:::shop-invoices-dr'}}]});
  const IT=()=>({Id:'unknown-media',Status:'Enabled',Filter:{Prefix:'photos/'},Tierings:[{Days:180,AccessTier:'ARCHIVE_ACCESS'},{Days:365,AccessTier:'DEEP_ARCHIVE_ACCESS'}]});
  function seed(){const base=name=>({name,region:'ap-south-1',public:false,encryption:true,bpa:{BlockPublicAcls:true,IgnorePublicAcls:true,BlockPublicPolicy:true,RestrictPublicBuckets:true},versioning:true,objects:[]});return {region:'ap-south-1',now:NOW,canBypassGovernance:true,roles:[{name:'shop-replication',replication:{trust:'s3.amazonaws.com',source:'shop-invoices',destination:'shop-invoices-dr',readRetention:true,readLegalHold:true}}],buckets:[{...base('shop-invoices'),versions:{'invoices/INV-301.pdf':[{versionId:'v-keep',body:'original invoice INV-301',etag:'"invoice-301"',size:2097152,storageClass:'STANDARD',lastModified:NOW}]}},{...base('shop-invoices-dr'),region:'us-east-1',versioning:undefined,versions:{}},{...base('shop-logs'),versions:{'logs/raw/event.json':[{versionId:'v-raw',body:'raw log',size:8192,storageClass:'STANDARD'}],'logs/aggregated/day.parquet':[{versionId:'v-aggregate',body:'aggregated logs',size:10485760,storageClass:'STANDARD'}]}},{...base('shop-media'),versions:{'photos/kurta.jpg':[{versionId:'v-photo',body:'public product image',size:1048576,storageClass:'INTELLIGENT_TIERING'}]}}]};}
  const bucket=(s,name)=>(s.account.buckets||[]).find(b=>b.name===name),version=(s,name,key,id)=>{const b=bucket(s,name),vs=b&&(b.versions||{})[key];return Array.isArray(vs)?vs.find(v=>v.versionId===id):null;};
  function eq(a,b){if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object')return false;const ak=Object.keys(a).sort(),bk=Object.keys(b).sort();return ak.length===bk.length&&ak.every((k,i)=>k===bk[i]&&eq(a[k],b[k]));}
  function lifecycle(s){const b=bucket(s,'shop-logs'),rows=b&&b.lifecycle&&b.lifecycle.Rules,strip=r=>{const {ID,...rest}=r;return rest;};return Array.isArray(rows)&&rows.length===3&&b.lifecycleMinimum==='all_storage_classes_128K'&&LC().Rules.every(e=>rows.some(r=>eq(strip(r),strip(e))));}
  function protectedInvoice(s){const b=bucket(s,'shop-invoices'),v=version(s,'shop-invoices','invoices/INV-301.pdf','v-keep');return !!b&&b.versioning&&eq(b.objectLock,LOCK())&&!!v&&v.retention&&v.retention.Mode==='COMPLIANCE'&&new Date(v.retention.RetainUntilDate)>=new Date(UNTIL);}
  function replication(s){const a=bucket(s,'shop-invoices'),b=bucket(s,'shop-invoices-dr');return !!a&&a.versioning&&!!b&&b.versioning&&b.region==='us-east-1'&&b.objectLock&&b.objectLock.ObjectLockEnabled==='Enabled'&&a.replication&&a.replication.Role===ROLE&&Array.isArray(a.replication.Rules)&&a.replication.Rules.length===1&&a.replication.Rules[0].Status==='Enabled'&&a.replication.Rules[0].Filter&&a.replication.Rules[0].Filter.Prefix==='invoices/'&&a.replication.Rules[0].Destination&&a.replication.Rules[0].Destination.Bucket==='arn:aws:s3:::shop-invoices-dr'&&a.replication.Rules[0].DeleteMarkerReplication&&a.replication.Rules[0].DeleteMarkerReplication.Status==='Disabled';}
  function tiering(s){const b=bucket(s,'shop-media'),v=version(s,'shop-media','photos/kurta.jpg','v-photo');return !!b&&eq((b.intelligentTiering||{})['unknown-media'],IT())&&!!v&&v.storageClass==='INTELLIGENT_TIERING';}
  function preserved(s){const a=seed();return (s.account.buckets||[]).length===4&&a.buckets.every(original=>{const b=bucket(s,original.name);return !!b&&!b.public&&b.encryption&&b.bpa&&['BlockPublicAcls','IgnorePublicAcls','BlockPublicPolicy','RestrictPublicBuckets'].every(k=>b.bpa[k]===true)&&Object.entries(original.versions).every(([key,rows])=>{const current=(b.versions||{})[key];return Array.isArray(current)&&current[0]&&current[0].versionId===rows[0].versionId&&rows.every(v=>{const kept=current.find(x=>x.versionId===v.versionId);return !!kept&&kept.body===v.body&&kept.size===v.size&&!kept.deleteMarker;});});})&&(s.account.roles||[]).some(r=>r.name==='shop-replication'&&eq(r.replication,a.roles[0].replication));}
  const file=v=>({content:JSON.stringify(v,null,2)});
  const SOLUTION=['aws s3api put-bucket-versioning --bucket shop-invoices-dr --versioning-configuration Status=Enabled','aws s3api put-bucket-lifecycle-configuration --bucket shop-logs --lifecycle-configuration file://lifecycle.json --transition-default-minimum-object-size all_storage_classes_128K','aws s3api put-object-lock-configuration --bucket shop-invoices --object-lock-configuration file://lock-seven-years.json','aws s3api put-object-retention --bucket shop-invoices --key invoices/INV-301.pdf --version-id v-keep --retention file://existing-invoice-retention.json','aws s3api put-object-lock-configuration --bucket shop-invoices-dr --object-lock-configuration file://dr-lock.json','aws s3api put-bucket-replication --bucket shop-invoices --replication-configuration file://replication.json','aws s3api put-bucket-intelligent-tiering-configuration --bucket shop-media --id unknown-media --intelligent-tiering-configuration file://tiering.json'];
  function plan(k){const size=[10,128,1024,10240,102400][k.size],count=[1e4,1e5,1e6,1e7][k.count],glacier=[30,60,90,180,300][k.glacier],gb=size*1024*count/2**30,eligible=size>=128||k.override===1,ia=Math.max(0,Math.min(365,k.ia)),gd=Math.max(ia,Math.min(365,glacier)),iaDays=gd-ia,glDays=365-gd,baseline=gb*0.023*12;
    const standard=gb*0.023*ia/365*12,iaStorage=Math.max(size,128)*1024*count/2**30*0.0125*iaDays/365*12,glStorage=((size+32)*1024*count/2**30*0.0036+8*1024*count/2**30*0.023)*glDays/365*12,transitions=count/1000*(0.01+0.03),readFraction=k.reads/100,readBytes=gb*readFraction*12,retrieval=readBytes*0.01*(iaDays+glDays)/365+count*readFraction*12/1000*0.05*glDays/365,early=Math.max(0,30-iaDays)/30*Math.max(size,128)*1024*count/2**30*0.0125+Math.max(0,90-glDays)/30*(size+32)*1024*count/2**30*0.0036,total=eligible?standard+iaStorage+glStorage+transitions+retrieval+early:baseline,saving=1-total/baseline,valid=ia>=30&&glacier>=ia+30,noPenalty=size>=128&&early===0,ok=gb>=100&&k.reads>=10&&eligible&&valid&&noPenalty&&saving>=0.50;return {size,count,gb,eligible,baseline,storage:eligible?standard+iaStorage+glStorage:baseline,transitions:eligible?transitions:0,retrieval:eligible?retrieval:0,early:eligible?early:0,total,saving,valid,noPenalty,ok};}
  function Q(q,correct,wrong,answer,explain,domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain,domain};}
  const table=html=>'<div class="tbl-wrap">'+html+'</div><p class="muted">Phone par baaki columns ke liye table sideways swipe karo.</p>';
  AG.registerLevels('intermediate',[{
    id:'s3adv',icon:'🪣',title:'S3 Advanced — tiny-object bill, seven-year retention aur DR evidence',badge:'Storage Strategist',
    hook:{when:'ShopKaro · three years of invoices/logs/photos · fictional course story',title:'"Archive sasta tha. Tiny logs ka bill aur delete risk kyun badha?"',text:'Priya ke course scenario mein storage bill approx ₹40,000/month cross hua. Ravi sab 8 KB logs archive karna chahta hai. Ex-intern ke delete se versioning ne invoices recover kar di, par finance ko stronger requirement hai: selected invoice versions 7 years tak permanently delete na hon. Cost class, data retention aur verified DR copy teen separate decisions hain; no specific law assumed.'},
    objectives:['<b>Cost decision</b>: seven general-purpose classes, minimums and request/retrieval charges compare karo','<b>Granularity</b>: tiny objects aggregate before transition; current 128 KB lifecycle default samjho','<b>Preservation</b>: default future retention vs existing-version compliance/legal hold distinguish karo','<b>Replication</b>: versioning, role, destination lock, new vs existing objects and RTC scope','<b>Restore/performance</b>: archived readability, temporary copy, multipart and prefix scale','<b>Evidence</b>: state-based config repair; real lab protection and restored bytes verify karo'],
    steps:[
      {q:'Storage price ke saath kaunse minimums aur retrieval costs compare karoge?',analogy:'Warehouse shelf rent cheap ho sakta hai, par each parcel handling, minimum booking and emergency pickup separate charge hote hain. Sirf shelf rate se annual bill decide nahi hota.',body:table('<table><tr><th>General-purpose class</th><th>Approx$/GB/month, US East first tier</th><th>Minimum</th><th>Retrieval</th></tr><tr><td>Standard</td><td>0.023</td><td>No duration/minimum billed size</td><td>ms; no per-GB retrieval fee</td></tr><tr><td>Intelligent-Tiering</td><td>0.023 /0.0125 /0.004 automatic online tiers</td><td>No minimum duration;128 KB auto-tier eligibility</td><td>Online tiers ms; optional archives require restore</td></tr><tr><td>Standard-IA</td><td>0.0125</td><td>30 days;128 KB billed minimum</td><td>ms; approx $0.01/GB read</td></tr><tr><td>One Zone-IA</td><td>0.010</td><td>30 days;128 KB; one AZ</td><td>ms; approx $0.01/GB read</td></tr><tr><td>Glacier Instant Retrieval</td><td>0.004</td><td>90 days;128 KB billed minimum</td><td>ms; approx $0.03/GB read</td></tr><tr><td>Glacier Flexible Retrieval</td><td>0.0036</td><td>90 days;40 KB extra metadata/object</td><td>Expedited typically1–5 min; Standard3–5h; Bulk5–12h</td></tr><tr><td>Glacier Deep Archive</td><td>0.00099</td><td>180 days;40 KB extra metadata/object</td><td>Standard typically12h; Bulk48h</td></tr></table>'),points:['Prices approximate2025–26 us-east-1 list rates, ₹88=$1; region/tier/request/taxes change invoice. Current public price catalogs verified this session; planner is a budget model, not AWS billing output.','Flexible/Deep metadata:8 KB charged at Standard rate +32 KB at archive rate. Glacier Instant128 KB minimum is a different rule. Minimum duration early deletion/transition can still incur remaining storage charge.','One Zone-IA only recreatable/secondary data where AZ-loss risk accepted. Storage class alone WORM or compliance guarantee nahi. Specialized Express One Zone uses directory-bucket/single-AZ low-latency design; separate choice from long-term archive.'],asli:'Action: bins game mein quarterly-ms requirement Glacier Instant se match karo. Flexible/Deep require restore; large objects/capacity can take longer than typical tier times.'},
      {q:'Access pattern unknown ho toh Intelligent-Tiering kya automate karta hai?',analogy:'Warehouse clerk har parcel ki last pickup activity track karta hai; unused stock cheaper shelves par shift hota hai. Har tiny label par clerk fee charge karna useful nahi.',body:'<p>Intelligent-Tiering online tiers:30 days no access → Infrequent;90 days → Archive Instant, still millisecond reads. Optional Archive Access (minimum90 days) and Deep Archive Access (minimum180 days) enable karoge toh restore delays accept karne padenge.</p>',points:['Monitoring/automation approx $0.0025 per 1,000 eligible objects/month. No retrieval fee; expedited restore, requests, transfer and optional-feature charges still need review. Auto-tier movement itself has no added tiering request fee.','Objects<128 KB remain Frequent tier, no monitoring charge, no auto-tier saving. Tiny-object workloads ke liye blindly Intelligent-Tiering choose mat karo.','Bucket Intelligent-Tiering configuration optional archive thresholds defines; Standard objects automatically convert nahi hote. Objects must use INTELLIGENT_TIERING storage class through PUT/COPY/lifecycle separately.','Unknown archive access tolerance alag decision hai. Pattern unknown means online automatic tiers candidate; optional slow archives without owner approval dangerous hain.'],asli:'Action: main mission media object already INTELLIGENT_TIERING hai. cat tiering.json mein photos/ prefix and180/365 day optional archive thresholds inspect karo; config storage-class conversion claim nahi karta.'},
      {q:'Lifecycle se bill kam kab; tiny-object trap kab?',analogy:'Courier har packet ko cold warehouse bhejne ka handling fee leta hai. Millions of tiny packets ko sealed larger batches mein pack karna cheaper ho sakta hai; batching retrieval granularity bhi badalti hai.',body:table('<table><tr><th>Lifecycle action</th><th>Explicit job</th><th>Boundary</th></tr><tr><td>Current transitions</td><td>Aggregated logs at30 days→IA,180 days→Flexible</td><td>Request charges, minimum durations, restore tolerance</td></tr><tr><td>Noncurrent transitions/expiration</td><td>Old versions separately age/clean</td><td>Current-only expiry does not remove version history</td></tr><tr><td>Abort incomplete multipart</td><td>Unused upload parts after7 days</td><td>Separate prefix rule; not deletion of completed objects</td></tr></table>'),points:['New/updated lifecycle default since September 2024 skips objects<128 KB for transitions to any class. Explicit object-size filters can override default; pre-existing old configurations may differ. Do not assume every8 KB log automatically archived by new default.','Approx per 1,000 transition requests:IA$0.01, Glacier Instant$0.02, Flexible $0.03, Deep$0.05.1 million objects Standard→IA→Flexible means approx $40 handling before storage/reads;10 million means$400.','One-rule chains must respect source class minimum transition spacing. Expiration/other-rule early moves can still produce minimum-duration charges. Automatic asynchronous lifecycle is not a precise instant timer.','Aggregate/compress logs when retention/query pattern allows. Keep index/retrieval granularity and audit requirements; changing object size by losing payload is not optimization. Retention-protected versions cannot be permanently expired before lock ends.'],asli:'Action: planner keep≥100 GiB and≥10% objects read/month, then try10 MiB batches. Mission lifecycle targets logs/aggregated/ with ObjectSizeGreaterThan131071; raw8 KiB logs retained outside transition prefix.'},
      {q:'Replication config ke baad actual DR copy ka proof kya hoga?',analogy:'Courier contract sign karna parcel destination par delivered hone ka proof nahi. Both warehouses ke version labels, access badges and delivery status chahiye.',body:'<pre>Source versioning + destination versioning\n + S3-trusted replication role and scoped permissions\n + enabled prefix rule → asynchronous new-object replication\n + destination version/data/status verification\nExisting objects → separate Batch Replication workflow</pre>',points:['SRR same-region copy; CRR cross-region copy. Cross-region increases failure independence, but data-residency rules/ownership/KMS permissions review mandatory; more countries automatically compliant nahi.','Default live replication covers eligible new writes after rule, not a historical backfill. Delete-marker replication optional; version-ID deletes and lifecycle-expiration marker behavior differ. Replica is not an independent immutable backup unless retention/access design provides protection.','Object Lock source enabled ho toh destination also enabled; role needs GetObjectRetention aur GetObjectLegalHold in addition to replication permissions. Source retention metadata replicates; next card fixed retention explains protection.','Optional S3 RTC covers99.99% of new objects within 15 minutes under SLA/conditions. Not synchronous zero-RPO, not a per-object universal guarantee. Track replication metrics/status/failures and verify restored application behavior.'],asli:'Action: enable destination versioning before put-bucket-replication. Current simulator checks configuration prerequisites, does not claim a replica copy; Moto lab destination stayed empty despite saved rule.'},
      {q:'Seven-year WORM mein default retention, existing version aur legal hold ka difference?',analogy:'New invoice ke automatic seal rule se old unsealed file protected nahi ho jaati. Named old file par explicit seal chahiye; court hold fixed expiry ke alawa independent stop flag hai.',body:table('<table><tr><th>Control</th><th>Protection</th><th>Debug detail</th></tr><tr><td>Bucket default retention</td><td>New object versions get selected duration</td><td>Existing versions need explicit/batch retention</td></tr><tr><td>Governance retention</td><td>Most users cannot permanently delete protected version</td><td>Authorized bypass permission + explicit flag can override</td></tr><tr><td>Compliance retention</td><td>No version delete/shorten, including root, during active retention</td><td>Governance bypass flag cannot override</td></tr><tr><td>Legal hold</td><td>Independent ON until authorized OFF</td><td>Governance bypass does not remove hold</td></tr></table>'),points:['Object Lock requires versioning; can enable on existing versioned general-purpose bucket now. Once enabled, cannot disable Object Lock or suspend versioning. Retention-protected data encryption key still must remain accessible.','Protection attaches to a version. Simple DELETE can add delete marker and hide latest key; protected version remains. New PUT creates another version; not in-place overwrite of protected old version.','Course fixed retention uses7calendar years from fixture2026-10-26 to2033-10-26. Existing v-keep explicitly retained; default Years=7 handles future invoices. No legal mandate inferred from course finance requirement.','Real lab uses1 day governance with cleanup bypass, not7 year compliance. Latest AWS also has variable/event retention options; current exercise deliberately focuses fixed retention and legal hold.'],asli:'Action: mission cat lock-seven-years.json then existing-invoice-retention.json compare karo. Skipping existing-version retention cannot win even when bucket default looks correct.'},
      {q:'Archive restore aur upload performance ka practical plan kya hai?',analogy:'Cold warehouse se temporary reading copy milti hai; original parcel cold storage mein reh sakta hai. Large shipment parts mein bhejna retryable hai; one failed part ke liye poora shipment repeat nahi.',body:'<p>GLACIER/DEEP_ARCHIVE object GET before restore can return InvalidObjectState. restore-object request submit karo, head-object Restore metadata poll until ongoing-request=false, then read exact version and verify bytes. Temporary copy expiry ke baad original archive remains; permanent class change needs separate reviewed copy.</p>',points:['Glacier Instant is immediately readable and does not use archive restore. Flexible/Deep tiers have distinct time/fee/capacity trade-offs; expedited unavailable for Deep Archive. Real delays minutes/hours; simulator uses explicitly documented poll transitions.','Per partitioned prefix AWS documents at least 3,500 PUT/COPY/POST/DELETE and 5,500 GET/HEAD requests/second. Automatic scaling gradual; parallel prefixes/requests, retry/backoff and byte-range reads help. Not a hard per-bucket maximum.','Consider multipart around 100 MB+; single PUT limit 5 GB, larger requires multipart. Current maximum object size documented 50 TB since December 2025 (multipart part/count constraints determine exact binary ceiling); old 5 TB cap stale hai.','S3 Transfer Acceleration can help geographically distant uploads via AWS edge path; test actual speed and added charges. CDN download caching and upload acceleration separate tools hain.'],asli:'Action: interview restore mission has no invented restore-completed waiter. Model requires restore request, two head-object polls, then get-object to an in-memory output with original version/body checked; actual AWS elapsed time is not modeled.'},
      {q:'Upload event aur per-app shared-bucket access kaise design karein?',analogy:'Warehouse arrival bell ek event signal hai, parcel content process karne ka guarantee nahi. Har team ka dedicated counter permission entry point de sakta hai without cloning the full warehouse.',body:table('<table><tr><th>Requirement</th><th>Candidate</th><th>Boundary</th></tr><tr><td>Process object after upload</td><td>S3 notification → Lambda function, SNS topic or SQS queue; EventBridge integration</td><td>Duplicate/out-of-order delivery; idempotent processor and permissions</td></tr><tr><td>Per-app policy path to shared bucket</td><td>S3 access point, optionally VPC-restricted</td><td>Bucket policy/IAM still participate; not automatic public/private conversion</td></tr><tr><td>Historical object processing/copies</td><td>Inventory + Batch Operations/Batch Replication</td><td>Live notification/replication rule does not backfill history</td></tr></table>'),points:['Source event and derived output prefixes separate rakho; processor same event prefix mein output write kare toh recursive work/cost ho sakta hai. Queue/function details upcoming levels mein build honge.','Use bucket/key/version/event identifiers for duplicate-safe processing. Event notification is not exactly-once business transaction or guaranteed ordering.','Access point policy, bucket delegation and calling identity permissions jointly review karo. VPC-only access point limits network access context; encrypted content confidentiality still needs correct authorization.'],asli:'Interview follow-up: one shared bucket per-app access solve karna hai, har app ko admin bucket policy dena needed? Nahi. Scoped access point plus matching bucket/IAM policy and network context review karo.'},
      {q:'Encryption enable hone se retention/compliance aur access automatically solve hote hain?',analogy:'Locked cabinet key ka ownership file-delete rules aur authorized readers se separate hai. Disk encryption valid key holder ko data de sakti hai; cabinet key destroy ho toh retained file bhi unreadable ho sakti hai.',body:'<p>New S3 object uploads default SSE-S3 encrypted at rest hain. SSE-KMS adds reviewed KMS key permissions, audit/control and request/key costs; S3 Bucket Keys can reduce KMS request traffic in supported designs. Encryption does not repair public policy or extend Object Lock retention.</p>',points:['Customer-managed symmetric KMS key automatic rotation opt-in/configuration hai; blanket automatic rotation for every key incorrect. AWS-managed key rotation and asymmetric/imported-key behavior differ.','KMS policy, role permissions, encryption context and cross-account/cross-region key availability matter. Replication of SSE-KMS objects needs explicit settings/permissions; this lab uses SSE-S3 to isolate retention behavior.','Minimum storage bill, monitoring, transitions, restore requests/data, temporary restored storage, replication requests/transfer and KMS are separate cost meters. Readiness needs an estimate plus observed data/permission/recovery evidence.'],asli:'Action: planner gross annual estimate inspect karo; compare storage, per-object transitions, retrieval and early-duration charges. At least 50% saving must preserve payload, read demand and retention/recovery constraints.'},
    ],
    myth:[{myth:'Cheap archive class means automatic80% saving and compliance.',sach:'Har object ki transition fee, archive metadata, retrieval aur minimum storage charges matter. Class choice does not make WORM; protected version retention and encryption-key availability separate.'},{myth:'Default 7 year compliance also locks all old invoices immediately.',sach:'Bucket default applies to new versions. Existing invoice version needs explicit/batch retention; fixed mode/date and protected original version must be inspected.'},{myth:'Object Lock means no DELETE can change a key; governance bypass beats every lock.',sach:'Simple DELETE can add marker and hide latest key. Protected version remains. Governance permission+flag cannot bypass active compliance or legal hold.'},{myth:'Saved replication rule means old files copied, zero RPO and instant archive reads.',sach:'Live rule covers eligible new writes; existing data needs Batch Replication. Verify actual replicas/status; RTC has SLA scope. Archived GET needs completed restore.'}],
    playbook:{title:'Kab use karein / kab nahi — cost, retention and recovery',use:['Unknown-changing access and eligible object size → online Intelligent-Tiering candidate','Predictable infrequent/quarterly/archive workloads → class based on latency and total cost','Version-level WORM requirement → reviewed fixed compliance/governance/legal hold design','DR copies → versioned scoped replication plus actual destination verification'],avoid:['Forced tiny-object archive transitions without per-object cost model','One Zone-IA for sole irreplaceable original','Default retention as historical backfill, replication metadata as delivered DR proof','Seven-year compliance on disposable real AWS lab requiring immediate cleanup'],how:['Record payload bytes, object count, read volume, retention and restore deadline','Compare minimum billed size/duration, transition/monitor/read fees and restore copy cost','Aggregate/compress where allowed; preserve payload/read/index constraints','Enable/verify versioning, apply selected bucket default and explicit existing-version retention','Review role/lock/KMS destination prerequisites; observe actual copies and restore bytes'],redflags:['Millions of8 KB objects with explicit default override','Only current-version expiry; old versions/incomplete uploads still billed','Missing dest versioning/lock; unsupported emulator returns empty config','Delete marker interpreted as destruction; restore requested interpreted as completed'],rule:'Decision tree: unknown access? eligible Intelligent-Tiering. Known access + ms? Standard/IA/Glacier Instant by frequency/minimums. Hours okay? Flexible/Deep by deadline/cost. WORM? separate Object Lock version policy. Region recovery? CRR + verified data/permission readiness, not just rule.'},
    exam:[{cue:'"unknown/changing access"',pick:'Intelligent-Tiering, eligible object size',why:'Online 30/90 day tiers; optional slow archives opt-in.'},{cue:'"quarterly access but milliseconds"',pick:'Glacier Instant Retrieval',why:'Not Flexible/Deep restore;90 day minimum and retrieval charge.'},{cue:'"lowest archive cost;12/48h acceptable"',pick:'Deep Archive candidate',why:'180 day minimum, requests/metadata/restore costs and actual deadline still review.'},{cue:'"WORM even root cannot delete"',pick:'Active Object Lock compliance on exact version',why:'Not governance-only; default does not backfill old versions.'},{cue:'"replicate existing objects"',pick:'Batch Replication',why:'New live rule alone historical backfill nahi.'},{cue:'"replication within 15 min SLA"',pick:'S3 RTC',why:'99.99% of eligible new objects under SLA/conditions, not zero-RPO universal guarantee.'},{cue:'"object upload>5 GB"',pick:'Multipart upload',why:'Consider around 100 MB+, current max documented 50 TB; old 5 TB cap stale.'},{cue:'"far-away uploads"',pick:'Evaluate Transfer Acceleration',why:'Measure network benefit and added cost; different from CDN downloads.'},{cue:'"process on upload / per-app shared-bucket policy"',pick:'Event notification / access point',why:'Duplicate-safe processing; access point + bucket/IAM policy review.'}],
    stages:[
      {type:'dryrun',title:'🔍 One invoice: cost class, lock and eventual recovery',goal:'Agla step par one state transition dekho. Compliance deletion and existing-version scope ke two decisions answer karo.',nodes:[N('user',140,85,{label:'Finance'}),N('s3',470,85,{label:'Invoice v-keep'}),N('lock',820,85,{label:'Compliance lock',icon:'🔒'}),N('s3#ia',470,275,{label:'IA / 30 days'}),N('s3#archive',800,440,{label:'Archive / 365 days'}),N('backup',140,440,{label:'Restore copy'}),N('s3#dr',140,275,{label:'DR version'})],edges:[{from:'user',to:'s3'},{from:'s3',to:'lock'},{from:'s3',to:'s3#ia'},{from:'s3#ia',to:'s3#archive'},{from:'s3',to:'s3#dr'},{from:'s3#archive',to:'backup'}],panels:[{id:'cost',title:'Separate cost meters'},{id:'lock',title:'Version protection / recovery'}],steps:[
        {clock:'day 0',say:'One 2 MiB invoice Standard mein upload hui. Fixed compliance version retention 2033-10-26 tak hai. Region/date and data are course fixtures; legal mandate assumed nahi.',flows:[{from:'user',to:'s3',tone:'ok'},{from:'s3',to:'lock',tone:'ok'}],panels:{cost:['Standard approx $0.023/GB/month','Requests, keys and replicas separate'],lock:['Protection belongs exact object version','Bucket default affects future versions']}},
        {clock:'day 30',say:'Separate archival policy eligible invoice version ko IA mein transition kar sakti hai; retention stays attached. Current/old-version lifecycle and minimum durations separately plan karo. Main mission invoice retention ko log cleanup se separate bucket mein rakhti hai.',flows:[{from:'s3',to:'s3#ia',tone:'ok'}],panels:{cost:['One transition request per object','IA30 day/128 KB billed minimum'],lock:['Class change does not remove WORM']}},
        {clock:'day 365',say:'Illustrative long-lived archive path Flexible Retrieval use karta hai. One per-object transition +40 KB metadata overhead. Same path millions of8 KB packets par costly ho sakta hai; new default skips small objects unless overridden.',flows:[{from:'s3#ia',to:'s3#archive',tone:'slow'}],panels:{cost:['8 KB metadata Standard rate +32 KB archive rate','Transition fees and retrieval still matter']}},
        {clock:'delete attempt',say:'Root caller exact retained version permanently delete karne ki koshish karta hai. Compliance retention still active. Simple delete marker operation separate visibility behavior hai.',ask:{q:'Active compliance version: root + governance bypass flag permanently delete kar sakte hain?',choices:['Nahi; compliance cannot be bypassed or shortened during active retention','Haan; governance bypass flag converts every compliance lock into a normal version','Haan; Glacier class stores only metadata so original retained version can be deleted','Nahi; Object Lock forbids creating any new version or adding a delete marker'],answer:0,explain:'Active compliance protects exact version even root/bypass cannot delete. Storage class does not remove lock. New versions/markers can exist; visibility differs from permanent deletion.'},panels:{lock:['AccessDenied for protected version deletion','Delete marker can hide latest key; version still retained']}},
        {clock:'old invoice',say:'Another invoice already existed before default retention set. Default alone old version ko retroactively protect nahi karti; explicit retain-until metadata inspect/apply karna needed hai.',ask:{q:'Bucket default Years7 correct, old version has no retention. Required repair?',choices:['Apply reviewed explicit compliance retention to existing version, then inspect mode/date','Wait for default policy to backfill all historical versions without any action','Add lifecycle Expiration Days1 so retained history is automatically reconstructed','Enable an optional archive tier and assume storage-class name creates WORM'],answer:0,explain:'Existing version needs explicit/batch retention. Default is for new versions; early expiration deletes eligibility, not retention repair; archive class is not lock.'},panels:{lock:['Default policy≠historical version retention']}},
        {clock:'audit restore',say:'Archived invoice restore submit hua; poll until readable, then verify exact version/body. DR rule metadata is not delivered copy; real destination/status/bytes need separate evidence.',flows:[{from:'s3#archive',to:'backup',label:'temporary readable copy',tone:'ok'},{from:'s3',to:'s3#dr',label:'async config≠delivery',tone:'slow'}],panels:{cost:['Restore request/data + temporary copy storage may charge'],lock:['Original archive/retention remains','Real restore elapsed time not modeled']}},
      ],lesson:'Class prices optimize storage access; lock protects exact version; replication/restore readiness needs actual data evidence. No flat saving or zero-RPO promise.'},
      {type:'flowlab',title:'🎛️ Annual cost — tiny files vs useful batches',goal:'Keep ≥100 GiB payload and at least 10% objects read/month. Model annual saving ≥50% vs Standard, valid transition chain, no small-object/early-duration penalty. Shrinking payload/read demand cannot win.',scenario:'One log cohort retired at 365 days; invoice retention is a separate workload; budget unit 1 GB = 2^30 bytes, object sizes KiB. Current data Standard→IA→Flexible; no payload discarded. IA transition $0.01/1,000, Flexible $0.03/1,000; archive 40 KiB metadata/object. Approx US East 2025–26 storage rates from lesson; retrieval modeled $0.01/GB for IA/Standard Flexible plus $0.05/1,000 Flexible restore requests. Tiny objects default skip; override deliberately exposes penalty. Gross annual estimate, not invoice; PUT/other GET/transfer/KMS/replication/tax extra; ₹88/$1.',knobs:[{id:'size',label:'Object size',min:0,max:4,step:1,value:0,labels:{0:'10 KiB',1:'128 KiB',2:'1 MiB',3:'10 MiB',4:'100 MiB'}},{id:'count',label:'Object count',min:0,max:3,step:1,value:3,labels:{0:'10,000',1:'100,000',2:'1 million',3:'10 million'}},{id:'ia',label:'IA transition age',min:15,max:90,step:15,value:30,unit:' days'},{id:'glacier',label:'Flexible transition',min:0,max:4,step:1,value:3,labels:{0:'30 days',1:'60 days',2:'90 days',3:'180 days',4:'300 days'}},{id:'reads',label:'Objects read/month',min:0,max:50,step:10,value:10,unit:'%'},{id:'override',label:'Small-size override',min:0,max:1,step:1,value:0,labels:{0:'Off / default',1:'On / force tiny'}}],model:k=>{const b=plan(k);return {readouts:[{label:'Payload preserved',value:b.gb.toFixed(1)+' GiB',tone:b.gb>=100?'ok':'bad'},{label:'Approx annual storage',value:'$'+b.storage.toFixed(2),tone:'info'},{label:'Transitions / retrieval',value:'$'+b.transitions.toFixed(2)+' / $'+b.retrieval.toFixed(2)+' per year',tone:'info'},{label:'Early-duration charge',value:'$'+b.early.toFixed(2)+'/year',tone:b.early===0?'ok':'bad'},{label:'Approx annual total / baseline',value:'$'+b.total.toFixed(2)+' / $'+b.baseline.toFixed(2),tone:b.saving>=0.50?'ok':'bad'},{label:'Modeled saving',value:(b.saving*100).toFixed(1)+'%',tone:b.saving>=0.50?'ok':'bad'},{label:'Config / object minimums',value:!b.eligible?'Tiny objects skipped by default':!b.valid?'Invalid single-rule transition ages':b.noPenalty?'Minimums respected':'Small-object/early-duration penalty',tone:b.eligible&&b.valid&&b.noPenalty?'ok':'bad'}],verdict:{ok:b.ok,text:b.ok?'Payload/read demand, minimums and annual cost goal pass teaching estimate. Review real retrieval granularity and invoice before migration.':'Example: 10 MiB × 100,000 objects, IA 30 days, Flexible 180 days, reads 10%, override Off. Batching keeps about 976.6 GiB and avoids tiny-object overhead/handling dominance.'}};},check:k=>plan(k).ok,lesson:'Change object granularity without losing bytes or required read demand. 10 MiB × 100,000 means about 976.6 GiB, two transitions 100,000 each. Default 10 KiB objects skip transitions; forcing small files can raise total through per-object charges. Actual aggregation format/query cost and sustained access vary.'},
      {type:'bins',title:'🗂️ Workload → storage class',instructions:'Frequency, retrieval deadline, recoverability and minimum duration ek saath use karo.',bins:[{id:'standard',label:'Standard'},{id:'it',label:'Intelligent-Tiering'},{id:'ia',label:'Standard-IA'},{id:'one',label:'One Zone-IA'},{id:'instant',label:'Glacier Instant'},{id:'flex',label:'Glacier Flexible'},{id:'deep',label:'Deep Archive'}],items:[{text:'Hot website assets, daily reads',bin:'standard',explain:'Frequent reads; no per-GB retrieval fee.'},{text:'Large objects, unknown changing access, online retrieval needed',bin:'it',explain:'Eligible online automatic tiers; slow archive options only if agreed.'},{text:'Infrequent multi-AZ backup, ms reads, held>30 days',bin:'ia',explain:'IA fits latency/frequency; retrieval/minimums still estimate.'},{text:'Recreatable thumbnails, rare reads, accepted single-AZ loss',bin:'one',explain:'One Zone-IA only with recoverability/risk agreement.'},{text:'Quarterly archive read must return in milliseconds',bin:'instant',explain:'Glacier Instant, not asynchronous restore classes.'},{text:'Long archive, bulk restore5–12 hours acceptable',bin:'flex',explain:'Flexible bulk restore can fit; actual capacity/large-object bounds review.'},{text:'Multi-year archive, lowest storage rate,12–48 hours acceptable',bin:'deep',explain:'Deep candidate;180 day minimum and restore/readiness/retention separate.'}]},
      {type:'order',title:'🧱 Existing invoice compliance and DR setup',instructions:'Configuration dependencies ko order karo; final observation ko saved rule se confuse mat karo.',steps:[{text:'Define fixed retention, restore deadline and approved cleanup limits',explain:'Real long compliance retention intentionally irreversible during period; do not improvise on disposable data.'},{text:'Verify source and destination versioning enabled',explain:'Object Lock and replication depend on version-aware data.'},{text:'Enable appropriate Object Lock; apply future default and explicit existing-version retention',explain:'Default alone historical versions protect nahi karti; destination lock required for locked-source replication.'},{text:'Review S3 trust/role scope, lock/KMS permissions and destination ownership',explain:'Config acceptance does not certify every role/key/bucket permission.'},{text:'Enable filtered replication and observe new-object destination/version status',explain:'Existing objects need Batch Replication; rule metadata is not delivery.'},{text:'Test authorized restore/read bytes and protected-version deletion behavior',explain:'Recovery usability and retention evidence actual version/data operations se milti hain.'}]},
      {type:'triage',title:'🩺 Archive bill expected se zyada',symptom:'Course fixture: 10 million objects, 8 KiB each. An explicit object-size filter override allowed Flexible archive despite new small-object default. One transition request per object plus archive metadata dominates.',commands:[{cmd:'aws s3api get-bucket-lifecycle-configuration --bucket tiny-logs',out:'{"TransitionDefaultMinimumObjectSize":"all_storage_classes_128K","Rules":[{"ID":"force-tiny","Status":"Enabled","Filter":{"ObjectSizeGreaterThan":0},"Transitions":[{"Days":30,"StorageClass":"GLACIER"}]}]}',clue:true,note:'Explicit size predicate overrides default. New default alone would skip<128 KB objects.'},{cmd:'aws s3api list-objects-v2 --bucket tiny-logs --max-keys 2',out:'{"Contents":[{"Key":"events/a.json","Size":8192,"StorageClass":"GLACIER"},{"Key":"events/b.json","Size":8192,"StorageClass":"GLACIER"}],"IsTruncated":true}',clue:true,note:'8 KiB body/object; Flexible adds 40 KiB metadata and per-object transition fee.'},{cmd:'aws s3api get-bucket-encryption --bucket tiny-logs',out:'{"ServerSideEncryptionConfiguration":{"Rules":[{"ApplyServerSideEncryptionByDefault":{"SSEAlgorithm":"AES256"}}]}}',clue:false,note:'SSE-S3 present; encryption is not per-object archive handling cause.'},{cmd:'aws s3api get-bucket-versioning --bucket tiny-logs',out:'{}',clue:false,note:'No historical versions in this cost fixture; main driver is granularity/explicit override.'}],questions:[Q('Most direct cause of higher modeled archive bill?','Millions of tiny transitions plus 40 KiB/object archive metadata outweigh body savings',['New 128 KB default guarantees all tiny objects transition even without an override','SSE-S3 charges a KMS customer-key fee on every tiny object by default','Lack of bucket versioning makes archive storage automatically multiply by seven'],0,'Explicit override enables tiny transitions; fees and metadata dominate. Default skips tiny objects; SSE-S3 not customer KMS; no automatic sevenfold storage multiplier from unversioned data.','cost-optimized'),Q('Repair preserving logs and useful retrieval behavior?','Evaluate aggregation/compression, eligible-size filter and full request/retrieval cost',['Delete raw logs immediately before checking retention or whether batches contain all data','Enable public-read policy so per-object archive transition fees become free','Raise Object Lock retention to seven years because longer lock removes storage fees'],1,'Aggregation can reduce handling/metadata per payload; verify data/index/retention first. Deletion loses evidence, public access does not change rates, longer lock can increase retained cost.','cost-optimized')]},
      (function(){const tasks=[{text:'Logs-only lifecycle: sized aggregated transitions + noncurrent cleanup +7 day incomplete-upload abort',check:lifecycle},{text:'Future invoice default 7 year compliance AND existing v-keep retained at least 2033-10-26',check:protectedInvoice},{text:'Destination versioning+Object Lock and scoped invoice CRR metadata configured',check:replication},{text:'Already Intelligent-Tiering photo class +180/365 day archive config retained',check:tiering},{text:'All original versions, visible data, four private encrypted buckets/BPA and role preserved',check:preserved}];return {type:'terminal',title:'🖥️ Mission — archive config without losing protected originals',instructions:'ls and cat seven JSON files inspect karo. Source invoice bucket already versioned; destination not. Role-policy fixture is pre-reviewed, inspect role-policy.json. Existing invoice key/version invoices/INV-301.pdf / v-keep. Seven intended state changes; all API syntax real.',goal:'Configure logs lifecycle on shop-logs only; preserve raw/aggregated data. Set source invoice default COMPLIANCE Years7 AND explicit v-keep retention≥2033-10-26. Enable DR versioning/Object Lock then filtered replication using existing scoped role. Media photo already INTELLIGENT_TIERING; configure optional 180/365 day tiers. No public access, deleted/hidden originals or missing version protection. Fixture clock 2026-10-26; config only, no real aging/replica copies claimed.',account:seed(),files:{'lifecycle.json':file(LC()),'lock-seven-years.json':file(LOCK()),'existing-invoice-retention.json':file(RETENTION()),'dr-lock.json':file({ObjectLockEnabled:'Enabled'}),'replication.json':file(REPL()),'tiering.json':file(IT()),'role-policy.json':file({Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['s3:GetReplicationConfiguration','s3:ListBucket'],Resource:'arn:aws:s3:::shop-invoices'},{Effect:'Allow',Action:['s3:GetObjectVersionForReplication','s3:GetObjectVersionAcl','s3:GetObjectVersionTagging','s3:GetObjectRetention','s3:GetObjectLegalHold'],Resource:'arn:aws:s3:::shop-invoices/invoices/*'},{Effect:'Allow',Action:['s3:ReplicateObject','s3:ReplicateDelete','s3:ReplicateTags'],Resource:'arn:aws:s3:::shop-invoices-dr/invoices/*'}]})},tasks,success:AG.allOf(tasks),solution:SOLUTION.slice(),hints:SOLUTION.map((c,i)=>c+[' — nudge: destination prerequisite first',' — keep invoice retention separate from logs cleanup; read three rules',' — new-version default only; existing v-keep still needs explicit retention',' — stronger: target exact existing version, not just bucket default',' — locked source replication requires locked destination too',' — configured rule is not historical backfill or observed replica',' — final metadata: existing media class already eligible; optional archive thresholds only'][i]),successText:'Original versions retained/visible; invoice default and explicit existing-version compliance, scoped replication prerequisites, safe log lifecycle and media tiering metadata agree. Actual replica status, lifecycle execution, billing and real archive elapsed time remain separate evidence.'};})(),
      {type:'docker',title:'🐳 Lab12 — locked deletes and restored bytes',project:'12-s3-lifecycle-lock-replication',goal:'README ex1–ex5: prerequisites → lifecycle/replication metadata → governance/legal hold/marker → archive GET/restore/byte compare → scoped cleanup.',why:'Some real metadata/data operations verified; Moto tiering/size-filter/replication limitations explicitly remain. Lab uses cleanup-safe governance1 day, not irreversible7 year compliance.',steps:[{text:'README isolated environment, then scoped buckets/role. Source initially unversioned.',cmd:'cd aws-gurukul/docker-labs\n./start-moto.sh\nsource env.sh\ncd 12-s3-lifecycle-lock-replication\n# README Setup exports run karo.\nbash setup.sh\nsource .lab/resources.sh',expect:'Source initially unversioned; replication-before-versioning example returns InvalidRequest.'},{text:'Read input files, then run actual metadata/protection/restore exercises.',cmd:'cat lifecycle.json\nbash exercises.sh\nsource .lab/resources.sh',expect:'Lifecycle/replication persist; explicit size predicate dropped by Moto, tiering put errors/get empty. Protected version delete AccessDenied; legal hold also blocks bypass.'},{text:'Inspect exact version and temporary archive restore state; compare restored bytes.',cmd:'aws s3api head-object --bucket "$SRC" --key archive/history.txt --version-id "$ARCHIVE_VERSION"\ncmp .lab/invoice.txt .lab/restored.txt',expect:'StorageClass GLACIER; Restore ongoing-request="false" immediately in Moto; cmp exits0.'},{text:'Read cleanup, remove only saved lab resources.',cmd:'bash cleanup.sh',expect:'Two empty lists: saved bucket names and IAM role absent. No shared reset.'}],observe:Q('Moto stores replication but DR empty; restore immediate and byte cmp passes. Evidence?','Saved config/protected-delete behavior/restored bytes; no real replication or restore-time proof',['Measured cross-region zero-RPO delivery for every historical object and all future writes','A failed byte recovery because temporary restored copy must permanently change storage class','Verified auto-tier movement for every small object because an empty tiering get means enabled'],2,'Metadata and actual local restored bytes/protected deletes verified. No replication worker/time/auto-tier evidence; temporary copy can remain GLACIER; empty config is not configured tiering.','resilient')},
      {type:'quiz',title:'📝 Bonus — S3 cost, retention and recovery constraints',questions:[
        Q('Unknown changing access, objects>128 KB, online reads needed. Candidate?','Intelligent-Tiering online tiers; optional slow archive tiers require separate approval',['Glacier Deep Archive immediately because every unknown read can wait48 hours automatically','One Zone-IA for every original because unknown access means all data is reconstructible','Standard-IA with zero retrieval fees and no minimum duration for arbitrary daily deletion'],0,'Intelligent-Tiering automates online tiers for eligible objects. Deep latency not assumed; reconstructibility independent; IA has read fees/minimums.','cost-optimized'),
        Q('Invoice existed before bucket default compliance Years7. What else is required?','Apply/verify retention on the specific existing version or use reviewed batch retention',['Wait one DNS TTL because bucket defaults retroactively seal all historical versions','Move invoice to Deep Archive because storage-class name supplies compliance WORM automatically','Disable versioning to prevent future version IDs from bypassing the default invoice rule'],1,'Default applies new versions; existing version explicit/batch retention needed. DNS irrelevant; class not WORM; Object Lock bucket cannot suspend versioning.','secure'),
        Q('Locked source replication rule fails despite role ARN. Destination prerequisite?','Enable destination versioning and Object Lock; review source retention/legal-hold permissions',['Make destination public so CloudFront can write cross-region replica objects without role use','Turn off source versioning so a single unnamed object can be copied without lock metadata','Add a lifecycle Expiration rule so source retention is removed before every replication attempt'],2,'Locked source requires locked/versioned destination and extra read-lock permissions. Public access unrelated/unsafe; source versioning required; lifecycle does not remove active retention.','resilient'),
        Q('10million8 KB objects forced to Flexible archive. Why can saving disappear?','Per-object transition requests and40 KB metadata/object can dominate tiny body storage',['Flexible Retrieval charges a30 day minimum at exactly128 KB for each object in every case','Every S3 GET automatically creates seven permanent full-size replicas in all AWS Regions','Bucket default encryption makes all archive requests customer-managed KMS operations'],3,'Flexible metadata/handling matters; its minimum90 days and40 KB metadata differ from IA128 KB/30 days. GET does not create global replicas; SSE-S3 is not automatically CMK.','cost-optimized'),
        Q('Quarterly archive access must be milliseconds, retained>90 days. Class?','Glacier Instant Retrieval, with retrieval fee and128 KB billed-size minimum reviewed',['Glacier Flexible Retrieval because Standard restore always finishes before an ordinary GET','Deep Archive because its lowest storage price guarantees the same online read latency','One Zone-IA because every quarterly archive requirement permits losing irreplaceable originals'],0,'Glacier Instant fits ms archive access; fees/minimums matter. Flexible/Deep archived objects need restore; one-zone durability choice requires separate recoverability agreement.','high-performing'),
        Q('DELETE without version ID hides a compliance-locked invoice. What happened?','A delete marker can be current while protected data version remains retained underneath',['Compliance retention was bypassed because the caller omitted version ID intentionally','S3 automatically shortened all older retention dates to the delete request timestamp','Object Lock prevents new markers so the only possible outcome is permanent original deletion'],1,'Simple delete can add marker; protected version still exists and can be accessed by version with permission. No bypass/retention shortening; marker creation allowed.','secure'),
        Q('Live replication enabled today; yesterday invoices absent at DR. Required workflow?','Reviewed S3 Batch Replication for existing eligible objects, then verify destination data',['Wait15 minutes because RTC backfills all historical objects before processing new writes','Lower lifecycle transition age so old data becomes new replication traffic automatically','Enable Intelligent-Tiering monitoring because monitor fee includes historical DR copying'],2,'Live replication is not historical backfill; Batch Replication addresses existing data. RTC timing for eligible new replication; lifecycle/tiering do not create a backfill guarantee.','resilient'),
        Q('Archive restore request accepted. When can recovery be claimed?','After completed Restore state and successful read/version/body checks with permissions',['Immediately on request202 because all archive classes become Standard permanently','When get-bucket-replication returns a role ARN, even if archive GET is still denied','After enabling Object Lock because retained encrypted bytes are always immediately readable'],3,'Accepted restore is not completion; verify data read and version/content. Temporary restore does not change original class; replication config/lock do not make archive bytes immediately readable.','resilient'),
      ]},
    ],
    interview:{title:'🎤 Storage architecture and restore evidence',instructions:'Total cost, version protection and actual recovery evidence choose karo. Final CLI task reads exact archived version after modeled restore completion.',questions:[
      Q('One-rule Standard→IA15 days→Flexible30 days requested. Best review?','Reject invalid IA age/spacing; redesign valid transitions and minimum-duration budget',['Approve because every storage class minimum applies only to explicit bucket deletion','Approve because Flexible minimum90 days eliminates every prior IA billing requirement','Remove versioning because lifecycle transition rules only work on unversioned buckets'],0,'IA lifecycle age must be at least30 days and one-rule chain respect source minimum duration. Minimums affect transitions/deletion; versioning does not prohibit lifecycle.','cost-optimized'),
      Q('Governance bypass permission+flag present, legal hold ON. Can protected version delete?','No; legal hold independent, authorized OFF required before governance bypass can help',['Yes; bypass flag overrides legal hold and compliance on every retained version','Yes; legal hold only applies to bucket name and never to individual object versions','No; governance can never be bypassed, even with permission and explicit request flag'],1,'Legal hold remains independent. Governance can be bypassed with proper permission+flag; hold version-level and compliance cannot be bypassed through that flag.','secure'),
      Q('Object Lock enabled on source; KMS key destroyed. What guarantee remains?','Version deletion protection does not ensure decrypt/read recovery without encryption key access',['Automatic S3 plaintext recovery because Object Lock stores a second unencrypted copy','RTC instantly recreates every missing customer key before any archive object is read','Deep Archive overrides key-policy denial so compliance audits always return plaintext'],2,'Retention and key availability separate. No automatic plaintext/key reconstruction; RTC replicates eligible objects under configuration, not lost encryption keys; archive cannot override key policy.','resilient'),
      Q('High request workload: how interpret3,500 writes/5,500 reads per prefix guidance?','At-least per-partitioned-prefix scale guidance; parallelize and handle gradual scaling/retries',['A hard per-bucket maximum that cannot increase even with multiple prefixes or clients','A guaranteed fixed request rate for every object even before any workload scaling','An encryption requirement that forces all prefixes to use one customer-managed KMS key'],3,'AWS documents at-least per-prefix performance with gradual scaling/workload variation. Not fixed bucket ceiling/object guarantee; KMS quotas can be separate bottleneck, not mandated single key.','high-performing'),
      {terminal:(function(){const a=seed(),b=a.buckets.find(b=>b.name==='shop-logs'),body='dummy audit source';b.versions['archive/audit.txt']=[{versionId:'v-archive',storageClass:'GLACIER',body,size:body.length,etag:'"audit-v1"'}];const tasks=[{text:'Exact archived v-archive still GLACIER; restore completed/unexpired after explicit polls',check:s=>{const v=version(s,'shop-logs','archive/audit.txt','v-archive');return !!v&&v.storageClass==='GLACIER'&&v.restore&&v.restore.pollsRemaining===0&&new Date(v.restore.expires)>new Date(NOW)&&v.body===body;}},{text:'Output contains exact archived version/body/etag, not merely a typed GET',check:s=>{const d=s.downloads&&s.downloads['audit-restored.txt'];return !!d&&d.versionId==='v-archive'&&d.body===body&&d.etag==='"audit-v1"';}},{text:'Original invoices/logs/media, private buckets and role preserved',check:preserved}];const solution=['aws s3api restore-object --bucket shop-logs --key archive/audit.txt --version-id v-archive --restore-request file://restore.json','aws s3api head-object --bucket shop-logs --key archive/audit.txt --version-id v-archive','aws s3api head-object --bucket shop-logs --key archive/audit.txt --version-id v-archive','aws s3api get-object --bucket shop-logs --key archive/audit.txt --version-id v-archive audit-restored.txt'];return {title:'🖥️ Archive audit: restore, poll and verify exact version',goal:'archive/audit.txt / v-archive is GLACIER. cat restore.json, restore Standard tier for 2 days; model requires two head-object polls (first ongoing=true, second=false). Real AWS elapsed minutes/hours are not simulated and there is no restore-completed S3 waiter. Then get exact version into audit-restored.txt, an in-memory teaching output; body/version/etag are checked. Do not delete/re-upload original or substitute a fresh Standard object.',account:a,files:{'restore.json':file({Days:2,GlacierJobParameters:{Tier:'Standard'}})},tasks,success:AG.allOf(tasks),solution,hints:solution.map((c,i)=>c+[' — submit actual restore request, not a storage-class rename',' — first observation: ongoing-request=true in model',' — second observation advances documented fixture to complete; no real duration claim',' — final recovery read populates output with original version/body'][i]),successText:'Exact v-archive restored/read; in-memory output body="dummy audit source", etag="audit-v1". Original object remains GLACIER with expiring restored copy. Metadata poll count is a teaching transition; Moto lab verifies actual local restored bytes separately.'};})()},
    ]},
    success:['Storage class, object granularity and total request/read/minimum costs compare kar sakta hoon','Bucket default vs existing-version compliance/legal hold and delete markers explain kar sakta hoon','Replication prerequisites/configuration ko actual DR delivery se distinguish kar sakta hoon','Archived restore readiness and exact version/body evidence verify kar sakta hoon'],
    homework:'<p><b>Optional approved real AWS sandbox only; billable and retention-sensitive:</b> estimate region/object count/read/transition/restore/replication/KMS costs first. Use tiny disposable corpus with inventory/checksums. Test lifecycle configuration without waiting months or claiming instant movement; approve appropriate short GOVERNANCE retention and bypass permissions for cleanup. Do not apply seven-year COMPLIANCE to disposable real resources. Existing-version retention and default future retention inspect separately. Review versioned destination/lock/role/key prerequisites; upload approved new object and verify replication status and destination bytes; historical backfill needs Batch Replication. Archive one approved object only if restore delay/cost acceptable, poll real Restore metadata, verify exact version and bytes. Cleanup legal holds only with approval, bypass governance only with authorized flag, remove exact versions/markers/incomplete uploads, bucket replication/tiering/lifecycle settings, test buckets and scoped role/policies. Active COMPLIANCE cannot be bypassed for cleanup; preserved keys/shared datasets remain untouched.</p>',
    cards:[{front:'IA vs Glacier minimums?',back:'IA/One Zone-IA 30 days and128 KB minimum billed size. Glacier Instant 90 days/128 KB; Flexible 90 days and Deep 180 days, each adds 40 KB metadata (8 KB Standard+32 KB archive). Per-object/request/read fees matter.'},{front:'Intelligent-Tiering small objects?',back:'<128 KB remain Frequent tier, no monitoring charge/auto-tier. Online tiers 30/90 days; optional slow archives require explicit config. Standard objects do not convert just because config exists.'},{front:'New lifecycle tiny-object default?',back:'Since September 2024 new/updated configs default skip transitions<128 KB. Explicit size filters can override. Aggregation may reduce metadata/request cost, preserving payload/read/index requirements.'},{front:'Default 7 year retention protects old invoice?',back:'No. Default applies new versions. Apply/verify explicit or batch retention on existing version; compliance cannot be shortened/deleted even root during active retention.'},{front:'Delete marker vs protected version?',back:'Simple DELETE can hide latest key with marker; retained version remains. New versions allowed. Governance bypass cannot override compliance/legal hold.'},{front:'Replication rule proves DR?',back:'No. Versioning/role/lock/KMS prerequisites, observe actual new-object destination status/data. Existing objects need Batch Replication; RTC 99.99% within 15 min under SLA scope, not zero RPO.'},{front:'Restore accepted: object now Standard?',back:'No. Flexible/Deep temporary readable copy after completion; original archive class remains. Poll real state, read exact version/bytes before claiming recovery.'},{front:'Upload/performance current numbers?',back:'At least 3,500 write/5,500 read requests per second per partitioned prefix, gradual scaling. Multipart consider 100 MB+, required above 5 GB; maximum documented 50 TB since December 2025, not old 5 TB.'}],
  }]);
})();
